previewCss:
.thc-14,
.thc-14 *,
.thc-14 *::before,
.thc-14 *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.thc-14 {
  --acc: oklch(0.72 0.16 155);
  font-family: 'Segoe UI',system-ui,sans-serif;
  width: 100%;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 60px 24px 48px;
  background: linear-gradient(180deg,oklch(0.97 0.008 155),oklch(0.93 0.015 170));
}

.thc-14 .thc-14__card {
  position: relative;
  width: min(300px,100%);
  padding: 24px;
  border-radius: 20px;
  background: #fff;
  border: 1px solid oklch(0.9 0.01 160);
  transform: perspective(1100px) rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg));
  transform-style: preserve-3d;
  transition: transform .55s cubic-bezier(.2,.9,.3,1.1),box-shadow .55s ease;
  box-shadow: 0 18px 44px -30px oklch(0.4 0.08 160 / .6);
  cursor: pointer;
}

.thc-14 .thc-14__card.is-live {
  transition: transform .08s linear,box-shadow .4s ease;
  box-shadow: 0 30px 56px -26px oklch(0.4 0.1 160 / .65);
}

.thc-14 .thc-14__card:focus-visible {
  outline: 3px solid var(--acc);
  outline-offset: 4px;
}

.thc-14 .thc-14__pill {
  position: absolute;
  top: -14px;
  right: 18px;
  font: 700 11px 'Segoe UI',sans-serif;
  color: #fff;
  background: linear-gradient(120deg,var(--acc),oklch(0.6 0.14 190));
  border-radius: 999px;
  padding: 8px 14px;
  transform: translateZ(40px);
  box-shadow: 0 10px 22px -10px color-mix(in oklab,var(--acc) 80%,transparent);
  animation: thc-14-bob 3.8s ease-in-out infinite;
}

@keyframes thc-14-bob {
  50% {
    margin-top: -5px;
  }
}

.thc-14 .thc-14__thumb {
  width: 100%;
  aspect-ratio: 16/8;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: radial-gradient(80% 100% at 30% 20%,color-mix(in oklab,var(--acc) 35%,oklch(0.25 0.03 200)),oklch(0.22 0.03 220));
  transform: translateZ(18px);
}

.thc-14 .thc-14__glyph {
  font: 700 34px ui-monospace,monospace;
  color: color-mix(in oklab,var(--acc) 80%,white);
}

.thc-14 .thc-14__title {
  margin-top: 16px;
  font-size: 18px;
  font-weight: 700;
  color: oklch(0.24 0.02 200);
  transform: translateZ(24px);
  text-wrap: pretty;
}

.thc-14 .thc-14__meta {
  margin-top: 6px;
  font-size: 12px;
  color: oklch(0.55 0.02 200);
  transform: translateZ(12px);
}

.thc-14 .thc-14__track {
  margin-top: 16px;
  height: 8px;
  border-radius: 999px;
  background: oklch(0.93 0.01 160);
  overflow: hidden;
  transform: translateZ(20px);
}

.thc-14 .thc-14__fill {
  width: var(--progress,0%);
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg,var(--acc),oklch(0.62 0.14 190)),linear-gradient(115deg,transparent 40%,rgba(255,255,255,.55) 50%,transparent 60%);
  background-size: 100% 100%,300% 100%;
  background-position: 0 0,var(--mx,50%) 0;
  background-blend-mode: overlay;
}

.thc-14 .thc-14__cta {
  margin-top: 18px;
  width: 100%;
  height: 42px;
  border: none;
  border-radius: 11px;
  font: 600 13px 'Segoe UI',sans-serif;
  color: #fff;
  background: oklch(0.35 0.04 200);
  cursor: pointer;
  transform: translateZ(30px);
  transition: background .25s ease;
}

.thc-14 .thc-14__cta:hover {
  background: oklch(0.3 0.05 200);
}

.thc-14 .thc-14__cta:focus-visible {
  outline: 3px solid var(--acc);
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .thc-14 .thc-14__card {
    transition: none;
  }

  .thc-14__pill {
    animation: none;
  }
}

.ac-07,
.ac-07 *,
.ac-07 *::before,
.ac-07 *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.ac-07 {
  width: 100%;
  min-height: 100vh;
  min-height: 100svh;
  display: block;
  --ac-07-bg: oklch(0.97 0.008 145);
  --ac-07-card: oklch(1 0 0);
  --ac-07-ink: oklch(0.22 0.02 160);
  --ac-07-mut: oklch(0.54 0.02 160);
  --ac-07-acc: oklch(0.44 0.11 165);
  --ac-07-ok: oklch(0.62 0.16 148);
  --ac-07-line: oklch(0.22 0.02 160/.12);
  background: var(--ac-07-bg);
  color: var(--ac-07-ink);
  font-family: 'Segoe UI',system-ui,-apple-system,sans-serif;
  -webkit-font-smoothing: antialiased;
}

.ac-07__stage {
  min-height: 100vh;
  min-height: 100svh;
  display: grid;
  place-items: center;
  align-content: center;
  gap: clamp(14px,2.4vw,22px);
  padding: clamp(20px,5vw,58px);
}

.ac-07__bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  width: min(100%,720px);
  padding: 12px 16px;
  border: 1px solid var(--ac-07-line);
  border-radius: 16px;
  background: var(--ac-07-card);
}

.ac-07__brand {
  font-size: 14px;
  font-weight: 680;
  letter-spacing: -.02em;
}

.ac-07__cart {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 44px;
  height: 44px;
  color: var(--ac-07-ink);
}

.ac-07__badge {
  position: absolute;
  top: 2px;
  right: 0;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  display: grid;
  place-items: center;
  border-radius: 99px;
  background: var(--ac-07-acc);
  color: oklch(0.99 0 0);
  font-size: 11.5px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  transition: scale .3s cubic-bezier(.16,1,.3,1),opacity .2s;
  opacity: 0;
  scale: .5;
}

.ac-07__badge[data-on] {
  opacity: 1;
  scale: 1;
}

.ac-07__badge[data-pop] {
  animation: ac-07-pop .45s cubic-bezier(.16,1,.3,1);
}

@keyframes ac-07-pop {
  0% {
    scale: 1;
  }

  35% {
    scale: 1.45;
  }

  100% {
    scale: 1;
  }
}

.ac-07__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(280px,1fr));
  gap: 14px;
  width: min(100%,720px);
  list-style: none;
}

.ac-07__card {
  display: grid;
  grid-template-columns: 118px 1fr;
  gap: 0;
  border: 1px solid var(--ac-07-line);
  border-radius: 20px;
  overflow: hidden;
  background: var(--ac-07-card);
  box-shadow: 0 1px 2px oklch(0.22 0.02 160/.05),0 18px 34px -26px oklch(0.22 0.02 160/.6);
}

.ac-07__media {
  display: block;
  background: linear-gradient(135deg,oklch(0.88 0.03 160),oklch(0.82 0.05 130));
}

.ac-07__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.ac-07__body {
  display: grid;
  align-content: center;
  gap: 5px;
  padding: 16px;
}

.ac-07__name {
  font-size: 15.5px;
  font-weight: 650;
  letter-spacing: -.02em;
}

.ac-07__desc {
  font-size: 12.5px;
  color: var(--ac-07-mut);
}

.ac-07__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 8px;
}

.ac-07__price {
  font-size: 17px;
  font-weight: 680;
  font-variant-numeric: tabular-nums;
  letter-spacing: -.02em;
}

.ac-07__btn {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0,1fr);
  place-items: center;
  width: var(--ac-07-w,auto);
  min-width: 52px;
  height: 44px;
  padding: 0 var(--ac-07-p,20px);
  border: 0;
  border-radius: var(--ac-07-r,12px);
  background: var(--ac-07-acc);
  color: oklch(0.99 0 0);
  font-size: 13.5px;
  font-weight: 650;
  font-family: inherit;
  cursor: pointer;
  overflow: hidden;
  transition: width .38s cubic-bezier(.16,1,.3,1),padding .38s cubic-bezier(.16,1,.3,1),border-radius .38s cubic-bezier(.16,1,.3,1),background .3s,scale .12s;
}

.ac-07__btn:hover {
  background: color-mix(in oklch,var(--ac-07-acc) 88%,oklch(0 0 0));
}

.ac-07__btn:active {
  scale: .96;
}

.ac-07__btn:focus-visible {
  outline: 2px solid var(--ac-07-acc);
  outline-offset: 3px;
}

.ac-07__btn>* {
  grid-area: 1/1;
}

.ac-07__label {
  white-space: nowrap;
  transition: opacity .18s,scale .28s;
}

.ac-07__spin {
  width: 19px;
  height: 19px;
  flex: none;
  border-radius: 50%;
  border: 2.4px solid oklch(1 0 0/.32);
  border-top-color: oklch(1 0 0);
  opacity: 0;
  scale: .6;
  transition: opacity .18s,scale .28s;
}

.ac-07__check {
  width: 21px;
  height: 21px;
  flex: none;
  opacity: 0;
  scale: .6;
  transition: opacity .18s,scale .3s cubic-bezier(.16,1,.3,1);
}

.ac-07__check path {
  stroke-dasharray: 26;
  stroke-dashoffset: 26;
}

.ac-07__btn[data-state="pending"] {
  --ac-07-w: 52px;
  --ac-07-p: 0px;
  --ac-07-r: 99px;
}

.ac-07__btn[data-state="pending"] .ac-07__label {
  opacity: 0;
  scale: .8;
}

.ac-07__btn[data-state="pending"] .ac-07__spin {
  opacity: 1;
  scale: 1;
  animation: ac-07-spin .7s linear infinite;
}

.ac-07__btn[data-state="done"] {
  --ac-07-w: 52px;
  --ac-07-p: 0px;
  --ac-07-r: 99px;
  background: var(--ac-07-ok);
}

.ac-07__btn[data-state="done"] .ac-07__label {
  opacity: 0;
  scale: .8;
}

.ac-07__btn[data-state="done"] .ac-07__check {
  opacity: 1;
  scale: 1;
}

.ac-07__btn[data-state="done"] .ac-07__check path {
  animation: ac-07-draw .42s cubic-bezier(.6,0,.3,1) .05s forwards;
}

@keyframes ac-07-spin {
  to {
    rotate: 360deg;
  }
}

@keyframes ac-07-draw {
  to {
    stroke-dashoffset: 0;
  }
}

.ac-07__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.ac-07__chip {
  font-family: ui-monospace,Menlo,Consolas,monospace;
  font-size: 11.5px;
  line-height: 1.6;
  color: var(--ac-07-mut);
  padding: 8px 15px;
  border: 1px dashed var(--ac-07-line);
  border-radius: 99px;
  text-align: center;
  max-width: min(100%,700px);
}

@media (max-width: 420px) {
  .ac-07__card {
    grid-template-columns: 1fr;
  }

  .ac-07__media {
    aspect-ratio: 16/9;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ac-07 * {
    transition-duration: .01ms !important;
  }

  .ac-07__spin {
    animation-duration: 1.4s;
  }

  .ac-07__check path {
    stroke-dashoffset: 0;
    animation: none;
  }
}

@supports (color: oklch(50% .1 250)) {
  .av-15 {
    --page: oklch(97.6% .004 265);
    --panel: oklch(100% 0 0);
    --panel-2: oklch(96.4% .006 265);
    --ink: oklch(20% .022 265);
    --muted: oklch(53% .022 265);
    --line: oklch(92% .008 265);
    --accent: oklch(58% .196 272);
    --ok: oklch(58% .15 155);
    --bad: oklch(58% .19 30);
  }

  .av-15__init {
    background: oklch(93% .055 var(--h));
    color: oklch(44% .13 var(--h));
  }
}

.av-15 {
  --page: #f7f8fa;
  --panel: #ffffff;
  --panel-2: #f1f3f7;
  --ink: #10131a;
  --muted: #5f6672;
  --line: #e4e7ee;
  --accent: #4f46e5;
  --ok: #15803d;
  --bad: #c2410c;
  --glass: rgba(255,255,255,.68);
  --shadow: 0 1px 2px rgba(16,19,26,.05), 0 16px 36px -20px rgba(16,19,26,.3);
  --r: 18px;
  --size: clamp(4rem,11vw,5.5rem);
  width: 100%;
  inline-size: 100%;
  min-height: 100vh;
  min-height: 100svh;
  display: block;
  position: relative;
  background: var(--page);
  color: var(--ink);
  font-family: system-ui,-apple-system,"Segoe UI",sans-serif;
  -webkit-font-smoothing: antialiased;
}

.av-15 *,
.av-15 *::before,
.av-15 *::after {
  box-sizing: border-box;
}

.av-15__vh {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.av-15 [hidden] {
  display: none !important;
}

.av-15__theme {
  position: absolute;
  inset-block-start: clamp(.85rem,2.2vw,1.5rem);
  inset-inline-end: clamp(.85rem,2.2vw,1.5rem);
  z-index: 20;
  display: grid;
  place-items: center;
  inline-size: 2.5rem;
  block-size: 2.5rem;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--glass);
  color: var(--ink);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
  cursor: pointer;
  transition: translate .2s ease;
}

.av-15__theme::after {
  content: "";
  position: absolute;
  inset: -.4rem;
  border-radius: inherit;
}

.av-15__theme:hover {
  translate: 0 -1px;
}

.av-15__theme:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.av-15__i {
  inline-size: 1.15rem;
  block-size: 1.15rem;
}

.av-15__i--sun {
  display: none;
}

.av-15[data-theme="dark"] .av-15__i--moon {
  display: none;
}

.av-15[data-theme="dark"] .av-15__i--sun {
  display: block;
}

.av-15__stage {
  min-height: 100vh;
  min-height: 100svh;
  display: grid;
  place-items: center;
  padding: clamp(1.25rem,5vw,4rem);
}

.av-15__wrap {
  inline-size: min(56rem,100%);
  display: flex;
  flex-direction: column;
  gap: clamp(1.1rem,2.6vw,1.6rem);
}

.av-15__head {
  display: flex;
  flex-direction: column;
  gap: .4rem;
  padding-inline-end: 3.5rem;
}

.av-15__eyebrow {
  margin: 0;
  font-size: .7rem;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--muted);
}

.av-15__h {
  margin: 0;
  font-size: clamp(1.6rem,4.2vw,2.4rem);
  font-weight: 650;
  letter-spacing: -.03em;
  line-height: 1.05;
}

.av-15__sub {
  margin: 0;
  max-inline-size: 36rem;
  font-size: .95rem;
  line-height: 1.55;
  color: var(--muted);
  text-wrap: pretty;
}

.av-15__row {
  list-style: none;
  margin: 0;
  padding: clamp(1.5rem,4vw,2.25rem) clamp(1rem,3vw,1.75rem);
  display: grid;
  gap: clamp(1.25rem,3vw,2rem);
  grid-template-columns: repeat(auto-fit,minmax(9rem,1fr));
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--r);
  box-shadow: var(--shadow);
}

.av-15__cell {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .7rem;
  text-align: center;
}

.av-15__fig {
  position: relative;
  display: block;
  inline-size: var(--size);
  aspect-ratio: 1;
  border-radius: 50%;
  overflow: hidden;
  background: var(--panel-2);
  box-shadow: 0 0 0 1px rgba(16,19,26,.06);
}

.av-15__init {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: hsl(var(--h) 72% 92%);
  color: hsl(var(--h) 55% 30%);
  font-size: calc(var(--size) * .32);
  font-weight: 700;
  letter-spacing: .02em;
}

.av-15__img {
  position: absolute;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
  border-radius: 50%;
  object-fit: cover;
  object-position: center top;
  transition: opacity .3s ease;
}

.av-15__fig[data-state="broken"] .av-15__img {
  opacity: 0;
}

.av-15__fig[data-state="broken"] {
  box-shadow: 0 0 0 1px var(--line), 0 0 0 3px var(--panel);
}

.av-15__fig:has(img[data-broken]) .av-15__img {
  opacity: 0;
}

.av-15__who {
  display: flex;
  flex-direction: column;
  gap: .1rem;
}

.av-15__name {
  font-size: .92rem;
  font-weight: 600;
  letter-spacing: -.015em;
}

.av-15__meta {
  font-size: .75rem;
  font-weight: 600;
}

.av-15__meta--ok {
  color: var(--ok);
}

.av-15__meta--bad {
  color: var(--bad);
}

.av-15__bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .85rem 1.25rem;
  padding: .9rem 1.1rem;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.av-15__btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  min-block-size: 2.75rem;
  padding: 0 1rem;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: var(--ink);
  color: var(--panel);
  font: inherit;
  font-size: .86rem;
  font-weight: 600;
  cursor: pointer;
  transition: translate .16s ease, opacity .16s ease;
}

.av-15__btn svg {
  inline-size: 1.05rem;
  block-size: 1.05rem;
}

.av-15__btn:hover {
  translate: 0 -1px;
  opacity: .92;
}

.av-15__btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.av-15__live {
  margin: 0;
  font-size: .82rem;
  color: var(--muted);
}

.av-15[data-theme="dark"] {
  --page: #0a0b0e;
  --panel: #14161c;
  --panel-2: #1c1f27;
  --ink: #f2f4f9;
  --muted: #98a0b0;
  --line: #262a33;
  --accent: #8b8cf9;
  --ok: #4ade80;
  --bad: #fb923c;
  --glass: rgba(255,255,255,.07);
