}

.pb-22__loaded,
.pb-22__played {
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  border-radius: 99px;
}

.pb-22__loaded {
  inline-size: calc(var(--loaded,0) * 1%);
