}

.pb-22__played {
  inline-size: calc(var(--value,0) * 1%);
  background: linear-gradient(90deg,var(--accent),var(--accent-2));
}

.pb-22__dot {
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: calc(var(--value,0) * 1%);
  inline-size: .7rem;
  block-size: .7rem;
  border-radius: 99px;
  background: var(--ink);
  transform: translate(-50%,-50%);
