  inset-inline-start: 50%;
  transform: translate(-50%,-50%);
  font-size: .46rem;
  line-height: 1;
  font-weight: 700;
  letter-spacing: .02em;
  color: var(--ink);
  pointer-events: none;
}

.pb-22__ctl--play {
  inline-size: 3.4rem;
  block-size: 3.4rem;
  background: var(--ink);
